import{c as e,Q as a,j as o,m as r}from"./chunks/framework.BPKcPtvA.js";const u=JSON.parse('{"title":"LLM 核心原理","description":"","frontmatter":{},"headers":[],"relativePath":"03-large-models/llm-core.md","filePath":"03-large-models/llm-core.md"}'),n={name:"03-large-models/llm-core.md"};function l(i,t,d,s,h,c){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="llm-核心原理" tabindex="-1">LLM 核心原理 <a class="header-anchor" href="#llm-核心原理" aria-label="Permalink to &quot;LLM 核心原理&quot;">​</a></h1><blockquote><p>Token 机制、Context 窗口与采样控制 —— 驾驭大模型的基础能力</p></blockquote><h2 id="token-与-tokenization" tabindex="-1">Token 与 Tokenization <a class="header-anchor" href="#token-与-tokenization" aria-label="Permalink to &quot;Token 与 Tokenization&quot;">​</a></h2><p>LLM 不直接处理文本，而是处理 <strong>Token</strong>（词元）。Tokenization 是将文本切分为 Token 序列的过程。</p><h3 id="主流分词算法" tabindex="-1">主流分词算法 <a class="header-anchor" href="#主流分词算法" aria-label="Permalink to &quot;主流分词算法&quot;">​</a></h3><table tabindex="0"><thead><tr><th>算法</th><th>代表模型</th><th>特点</th></tr></thead><tbody><tr><td>BPE</td><td>GPT 系列</td><td>从字符级开始逐步合并高频对</td></tr><tr><td>WordPiece</td><td>BERT</td><td>基于似然的合并策略</td></tr><tr><td>SentencePiece</td><td>LLaMA, T5</td><td>语言无关，直接处理原始文本</td></tr><tr><td>Unigram</td><td>部分多语言模型</td><td>基于概率的减量式分词</td></tr></tbody></table><h3 id="关键概念" tabindex="-1">关键概念 <a class="header-anchor" href="#关键概念" aria-label="Permalink to &quot;关键概念&quot;">​</a></h3><ul><li><strong>词表大小（Vocabulary Size）</strong>：影响嵌入矩阵大小和计算量</li><li><strong>Special Tokens</strong>：<code>&lt;s&gt;</code>, <code>&lt;/s&gt;</code>, <code>&lt;pad&gt;</code>, <code>&lt;unk&gt;</code>, <code>&lt;|user|&gt;</code>, <code>&lt;|assistant|&gt;</code> 等</li><li><strong>Token 压缩率</strong>：中文约 1.5-2 字符/token，英文约 4 字符/token</li></ul><div class="tip custom-block"><p class="custom-block-title">工程实践</p><p>Token 计数直接影响 API 成本和 Context 窗口预算。在构建 Agent 系统时，需要精确控制 Prompt 的 Token 占用量。</p></div><h2 id="context-窗口" tabindex="-1">Context 窗口 <a class="header-anchor" href="#context-窗口" aria-label="Permalink to &quot;Context 窗口&quot;">​</a></h2><p>Context 窗口决定了模型单次能「看到」的 Token 数量上限。</p><h3 id="context-长度演进" tabindex="-1">Context 长度演进 <a class="header-anchor" href="#context-长度演进" aria-label="Permalink to &quot;Context 长度演进&quot;">​</a></h3><ul><li><strong>GPT-2</strong>：1,024 tokens</li><li><strong>GPT-3</strong>：2,048 tokens</li><li><strong>GPT-4</strong>：8K → 128K tokens</li><li><strong>Claude 3</strong>：200K tokens</li><li><strong>Gemini 1.5 Pro</strong>：1M tokens</li></ul><h3 id="位置插值与外推" tabindex="-1">位置插值与外推 <a class="header-anchor" href="#位置插值与外推" aria-label="Permalink to &quot;位置插值与外推&quot;">​</a></h3><p>超长 Context 需要特殊的扩展技术：</p><ul><li><strong>Position Interpolation</strong>：线性缩放位置索引</li><li><strong>NTK-aware Scaling</strong>：基于 Neural Tangent Kernel 的非线性缩放</li><li><strong>YaRN</strong>：结合 NTK 与温度调节的综合方案</li></ul><h3 id="注意力机制挑战" tabindex="-1">注意力机制挑战 <a class="header-anchor" href="#注意力机制挑战" aria-label="Permalink to &quot;注意力机制挑战&quot;">​</a></h3><p>长 Context 面临的计算瓶颈：标准注意力的复杂度为 $O(n^2)$，因此 FlashAttention、RingAttention 等高效实现成为长 Context 推理的必备技术。</p><hr><h2 id="采样参数控制" tabindex="-1">采样参数控制 <a class="header-anchor" href="#采样参数控制" aria-label="Permalink to &quot;采样参数控制&quot;">​</a></h2><p>理解以下参数是精确控制 LLM 输出的关键。</p><h3 id="temperature-温度" tabindex="-1">Temperature（温度） <a class="header-anchor" href="#temperature-温度" aria-label="Permalink to &quot;Temperature（温度）&quot;">​</a></h3><p>控制输出的随机性。在 softmax 之前进行调节：</p><p>$$ p_i = \\frac{\\exp(z_i / T)}{\\sum_j \\exp(z_j / T)} $$</p><table tabindex="0"><thead><tr><th>温度值</th><th>效果</th><th>适用场景</th></tr></thead><tbody><tr><td>$T \\to 0$</td><td>确定性输出</td><td>数学计算、代码生成</td></tr><tr><td>$T = 0.7$</td><td>平衡</td><td>通用对话、写作</td></tr><tr><td>$T &gt; 1.0$</td><td>高随机性</td><td>创意生成、头脑风暴</td></tr></tbody></table><h3 id="top-k-采样" tabindex="-1">Top-K 采样 <a class="header-anchor" href="#top-k-采样" aria-label="Permalink to &quot;Top-K 采样&quot;">​</a></h3><p>只从概率最高的 K 个 Token 中采样，截断低概率尾部。</p><h3 id="top-p-nucleus-sampling" tabindex="-1">Top-P（Nucleus Sampling） <a class="header-anchor" href="#top-p-nucleus-sampling" aria-label="Permalink to &quot;Top-P（Nucleus Sampling）&quot;">​</a></h3><p>从累积概率超过 P 的最小 Token 集合中采样。相比 Top-K 更灵活 —— 动态调整候选集大小。</p><h3 id="其他关键参数" tabindex="-1">其他关键参数 <a class="header-anchor" href="#其他关键参数" aria-label="Permalink to &quot;其他关键参数&quot;">​</a></h3><ul><li><strong>Repetition Penalty</strong>：惩罚已出现的 Token，防止重复</li><li><strong>Frequency Penalty</strong>：按出现频率惩罚</li><li><strong>Presence Penalty</strong>：按是否出现过惩罚</li></ul><hr><h2 id="预训练与后训练" tabindex="-1">预训练与后训练 <a class="header-anchor" href="#预训练与后训练" aria-label="Permalink to &quot;预训练与后训练&quot;">​</a></h2><h3 id="预训练-pre-training" tabindex="-1">预训练（Pre-training） <a class="header-anchor" href="#预训练-pre-training" aria-label="Permalink to &quot;预训练（Pre-training）&quot;">​</a></h3><p>在海量语料上进行自回归语言建模训练：</p><p>$$ \\mathcal{L} = -\\sum_{t} \\log P(x_t | x_{&lt;t}) $$</p><p>核心涉及：</p><ul><li>数据质量过滤与去重</li><li>混合精度训练（FP16/BF16）</li><li>分布式训练策略（数据并行、模型并行、流水线并行）</li></ul><h3 id="后训练-post-training" tabindex="-1">后训练（Post-training） <a class="header-anchor" href="#后训练-post-training" aria-label="Permalink to &quot;后训练（Post-training）&quot;">​</a></h3><h4 id="sft-监督微调" tabindex="-1">SFT（监督微调） <a class="header-anchor" href="#sft-监督微调" aria-label="Permalink to &quot;SFT（监督微调）&quot;">​</a></h4><p>在高质量指令-回复对上微调，使模型学会遵循指令格式。</p><h4 id="rlhf-人类反馈强化学习" tabindex="-1">RLHF（人类反馈强化学习） <a class="header-anchor" href="#rlhf-人类反馈强化学习" aria-label="Permalink to &quot;RLHF（人类反馈强化学习）&quot;">​</a></h4><ol><li>训练奖励模型（Reward Model）</li><li>使用 PPO 优化策略模型</li><li>可选：DPO 直接优化偏好，无需显式奖励模型</li></ol>',43)])])}const g=e(n,[["render",l]]);export{u as __pageData,g as default};
